// worktree-guard/hooks.test.mjs
//
// Exercises the two reference-transaction hooks generated by hooks.mjs
// against REAL git repositories in scratch temp directories -- no mocking of
// git itself, only of `ps` (see setupFakePs below) so ancestor-process
// detection tests are deterministic regardless of where this repo checkout
// happens to live on disk (this very worktree lives under a `.claude`
// directory, which would otherwise risk a false-positive AI-ancestor match
// against the real `node --test` process running these tests).
//
// Node built-ins only, zero third-party dependencies, ESM.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import {
  mkdtempSync,
  mkdirSync,
  rmSync,
  writeFileSync,
  readFileSync,
  chmodSync,
  existsSync,
  statSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { delimiter, join, resolve } from 'node:path';

import {
  isolatedFixtureGitEnv,
  withFixtureCommitIdentity,
} from '../support/isolated-git-env.mjs';

import {
  stashGuardHookScript,
  huskyForwardShimScript,
  installStashGuardHook,
  stashGuardStatus,
  computeStamp,
  installPrimaryLockHook,
  refreshPrimaryLockHookIfStale,
  primaryLockHookIsInstalled,
  sweepStaleSharedHooksPath,
  createBypassMarker,
  removeBypassMarker,
  primaryAuditLogPath,
} from '../../src/worktrees/hooks.mjs';
import { DEFAULT_CONFIG } from '../../src/worktrees/config.mjs';
import { matchesAiParentProcess } from '../../src/worktrees/process-provenance.mjs';

// ---------------------------------------------------------------------------
// Generic test helpers
// ---------------------------------------------------------------------------

function cloneConfig() {
  return JSON.parse(JSON.stringify(DEFAULT_CONFIG));
}

function tempDir(prefix) {
  return mkdtempSync(join(tmpdir(), prefix));
}

/**
 * Run git without asserting success; returns the spawnSync result with
 * stdout/stderr trimmed (git always emits a trailing newline on stdout --
 * leaving it in place silently corrupts anything built from `.stdout`, e.g.
 * a SHA passed as the next command's argv, or a path joined with it).
 */
function git(args, cwd, env) {
  const result = spawnSync('git', withFixtureCommitIdentity(args), {
    cwd,
    encoding: 'utf8',
    env: isolatedFixtureGitEnv(env || process.env),
  });
  return {
    ...result,
    stdout: (result.stdout || '').trim(),
    stderr: (result.stderr || '').trim(),
  };
}

/** Run git and throw with stderr context if it fails. */
function runOk(args, cwd, env) {
  const result = git(args, cwd, env);
  if (result.status !== 0) {
    throw new Error(`git ${args.join(' ')} failed in ${cwd}: ${result.stderr || result.stdout}`);
  }
  return result;
}

function initRepo(dir) {
  runOk(['init', '-q', '-b', 'main'], dir);
  writeFileSync(join(dir, 'seed.txt'), 'seed\n');
  runOk(['add', '.'], dir);
  runOk(['commit', '-q', '-m', 'init'], dir);
}

function cleanup(...dirs) {
  for (const dir of dirs) {
    rmSync(dir, { recursive: true, force: true });
  }
}

// ---------------------------------------------------------------------------
// Fake `ps` harness for deterministic ancestor-process control.
//
// The fake `ps` transparently forwards every query to the real `ps` binary
// EXCEPT for the single pid recorded in WTG_FAKE_PS_PID, for which it
// returns scripted WTG_FAKE_PS_COMMAND / WTG_FAKE_PS_PPID fields instead.
// Tests set WTG_FAKE_PS_PID to this Node process's own real pid -- which is
// genuinely the real OS parent pid of any `git` child process spawned
// directly via spawnSync below -- so the hook's ancestor walk transparently
// uses the real `ps` for the (uninteresting, always-"git") first hop, then
// hits the scripted answer at exactly the hop that represents "whatever
// process actually launched git", with no dependency on this test file's own
// real ancestry beyond that one pid.
// ---------------------------------------------------------------------------

const FAKE_PS_SCRIPT = `#!/bin/sh
field="$2"
target="$4"
if [ -n "$WTG_FAKE_PS_CHAIN" ]; then
  state_file="$PWD/.wtg-fake-ps-chain-state"
  if [ "$field" = "command=" ]; then
    index=$(cat "$state_file" 2>/dev/null || printf '0')
    index=$((index + 1))
    printf '%s\\n' "$index" > "$state_file"
    case "$index" in
      1) printf '%s\\n' 'C:\\Program Files\\Git\\mingw64\\bin\\git.exe commit' ;;
      2) printf '%s\\n' 'C:\\Program Files\\Git\\usr\\bin\\sh.exe -c hook' ;;
      3) printf '%s\\n' 'C:\\Program Files\\Git\\usr\\bin\\bash.exe -c hook' ;;
      4) printf '%s\\n' 'C:\\Windows\\System32\\conhost.exe --headless' ;;
      5) printf '%s\\n' 'C:\\Windows\\System32\\cmd.exe /d /c hook' ;;
      6) printf '%s\\n' "$WTG_FAKE_PS_CHAIN_FINAL" ;;
    esac
  elif [ "$field" = "ppid=" ]; then
    printf '%s\\n' "$((target + 1))"
  fi
  exit 0
fi
if [ "$1" = "-o" ] && [ "$3" = "-p" ] && [ -n "$WTG_FAKE_PS_PID" ] && [ "$target" = "$WTG_FAKE_PS_PID" ]; then
  case "$field" in
    command=) printf '%s\\n' "$WTG_FAKE_PS_COMMAND" ;;
    ppid=) printf '%s\\n' "$WTG_FAKE_PS_PPID" ;;
  esac
  exit 0
fi
exec "$WTG_REAL_PS" "$@"
`;

function findRealPs() {
  if (process.platform === 'win32') {
    const execPath = spawnSync('git', ['--exec-path'], { encoding: 'utf8' });
    const candidate = resolve((execPath.stdout || '').trim(), '../../../usr/bin/ps.exe');
    if (existsSync(candidate)) return candidate;
    throw new Error(`cannot locate Git for Windows ps.exe near ${execPath.stdout || 'git --exec-path'}`);
  }
  for (const candidate of ['/bin/ps', '/usr/bin/ps']) {
    if (existsSync(candidate)) return candidate;
  }
  const found = spawnSync('sh', ['-c', 'command -v ps'], { encoding: 'utf8' });
  const path = (found.stdout || '').trim();
  if (!path) throw new Error('cannot locate a real ps binary for the fake-ps test harness');
  return path;
}

function setupFakePs() {
  const dir = tempDir('wtg-fakebin-');
  const scriptPath = join(dir, 'ps');
  writeFileSync(scriptPath, FAKE_PS_SCRIPT);
  if (process.platform !== 'win32') chmodSync(scriptPath, 0o755);
  return { dir, realPs: findRealPs() };
}

const FAKE_PS = setupFakePs();

function resetFakePsChain(repo) {
  writeFileSync(join(repo, '.wtg-fake-ps-chain-state'), '0\n');
}

/**
 * Build an env for a primary-lock-hook-triggering git invocation, with the
 * fake-ps harness wired in and every relevant env var explicitly controlled
 * (never inherited ambiently from the outer test process).
 */
function primaryLockEnv(config, overrides = {}) {
  const env = { ...process.env };
  delete env[config.envVars.workerRole];
  delete env[config.envVars.primaryLockAllow];
  delete env[config.envVars.primaryLockBypass];

  env.PATH = `${FAKE_PS.dir}${delimiter}${env.PATH || ''}`;
  env.WTG_REAL_PS = FAKE_PS.realPs;
  env.WTG_FAKE_PS_PID = String(process.pid);
  env.WTG_FAKE_PS_COMMAND = overrides.fakeCommand ?? '/usr/bin/some-human-shell -i';
  env.WTG_FAKE_PS_PPID = overrides.fakePpid ?? '';
  if (overrides.fakeChain) {
    env.WTG_FAKE_PS_CHAIN = '1';
    env.WTG_FAKE_PS_CHAIN_FINAL = overrides.fakeChainFinal;
  } else {
    delete env.WTG_FAKE_PS_CHAIN;
    delete env.WTG_FAKE_PS_CHAIN_FINAL;
  }

  if (overrides.role !== undefined) env[config.envVars.workerRole] = overrides.role;
  if (overrides.primaryLockAllow !== undefined) {
    env[config.envVars.primaryLockAllow] = overrides.primaryLockAllow;
  }
  if (overrides.primaryLockBypass !== undefined) {
    env[config.envVars.primaryLockBypass] = overrides.primaryLockBypass;
  }
  if (overrides.extraEnv) Object.assign(env, overrides.extraEnv);
  return env;
}

// ---------------------------------------------------------------------------
// §A stash-guard
// ---------------------------------------------------------------------------

test('stash-guard: git stash push is blocked and refs/stash is not updated', () => {
  const config = cloneConfig();
  const dir = tempDir('wtg-stash-block-');
  try {
    initRepo(dir);
    installStashGuardHook(dir, config);
    writeFileSync(join(dir, 'seed.txt'), 'changed\n');

    const result = git(['stash', 'push', '-m', 'test'], dir);
    assert.notEqual(result.status, 0, 'git stash push should fail');
    assert.match(result.stderr, /BLOCKED/);

    const stashRef = git(['rev-parse', '--verify', 'refs/stash'], dir);
    assert.notEqual(stashRef.status, 0, 'refs/stash should not have been created');
  } finally {
    cleanup(dir);
  }
});

test('stash-guard: git stash apply succeeds because apply never updates refs/stash', () => {
  const config = cloneConfig();
  const dir = tempDir('wtg-stash-apply-');
  try {
    initRepo(dir);
    installStashGuardHook(dir, config);
    writeFileSync(join(dir, 'seed.txt'), 'changed-for-apply\n');

    // Pre-create the stash via the documented bypass (plumbing-equivalent:
    // this is the same escape hatch the forwarding shims themselves use),
    // simulating "a stash that already exists" without going through the
    // porcelain block under test.
    const bypassEnv = { ...process.env, [config.envVars.stashGuardAllow]: '1' };
    const pushed = git(['stash', 'push', '-m', 'apply-test'], dir, bypassEnv);
    assert.equal(pushed.status, 0, `setup: bypassed stash push should succeed: ${pushed.stderr}`);
    const sha = runOk(['rev-parse', 'refs/stash'], dir).stdout;

    // Now, with NO bypass env, apply from that sha -- must succeed because
    // `stash apply` performs a working-tree/index merge and never touches
    // refs/stash, so the "prepared" hook never even sees a stash-ref event.
    const applied = git(['stash', 'apply', sha], dir);
    assert.equal(applied.status, 0, `git stash apply should succeed: ${applied.stderr}`);
    assert.equal(readFileSync(join(dir, 'seed.txt'), 'utf8'), 'changed-for-apply\n');
  } finally {
    cleanup(dir);
  }
});

test('stash-guard: the allow-env escape hatch permits git stash push directly', () => {
  const config = cloneConfig();
  const dir = tempDir('wtg-stash-escape-');
  try {
    initRepo(dir);
    installStashGuardHook(dir, config);
    writeFileSync(join(dir, 'seed.txt'), 'escape-hatch\n');

    const env = { ...process.env, [config.envVars.stashGuardAllow]: '1' };
    const result = git(['stash', 'push', '-m', 'escape'], dir, env);
    assert.equal(result.status, 0, `expected success: ${result.stderr}`);

    const stashRef = runOk(['rev-parse', '--verify', 'refs/stash'], dir);
    assert.ok(stashRef.stdout.length > 0);
  } finally {
    cleanup(dir);
  }
});

test('stashGuardStatus reports installed+intact for a guarded worktree, not-installed for a plain one', () => {
  const config = cloneConfig();
  const guarded = tempDir('wtg-status-guarded-');
  const plain = tempDir('wtg-status-plain-');
  try {
    initRepo(guarded);
    installStashGuardHook(guarded, config);
    const guardedStatus = stashGuardStatus(guarded, config);
    assert.equal(guardedStatus.installed, true);
    assert.equal(guardedStatus.intact, true);
    assert.ok(guardedStatus.hooksPath);
    if (process.platform === 'win32') {
      const caseAlias = guarded.replace(/[a-z]/g, (letter, index) => (index % 2 === 0 ? letter.toUpperCase() : letter));
      assert.equal(stashGuardStatus(caseAlias, config).installed, true, 'drive/path casing cannot make an installed hook disappear');
    }

    initRepo(plain);
    const plainStatus = stashGuardStatus(plain, config);
    assert.equal(plainStatus.installed, false);
    assert.equal(plainStatus.hooksPath, null);
  } finally {
    cleanup(guarded, plain);
  }
});

test('stashGuardHookScript embeds the configured allow-env name; huskyForwardShimScript forwards to the real hooks path', () => {
  const config = cloneConfig();
  const script = stashGuardHookScript(config);
  assert.match(script, new RegExp(`\\$${config.envVars.stashGuardAllow}`));
  assert.match(script, /BLOCKED: git stash is disabled/);

  const shim = huskyForwardShimScript('pre-commit', config);
  assert.match(shim, /\.husky\/_\/pre-commit/);
  assert.match(shim, new RegExp(`export ${config.envVars.stashGuardAllow}=1`));
});

