test('primary-lock: a human/unrecognized context is allowed', () => {
  const config = cloneConfig();
  const dir = tempDir('wtg-primary-human-');
  try {
    initRepo(dir);
    installPrimaryLockHook(dir, 'test-owner', config);

    const env = primaryLockEnv(config);
    const result = git(['commit', '--allow-empty', '-q', '-m', 'human commit'], dir, env);
    assert.equal(result.status, 0, `expected allowed: ${result.stderr}`);
  } finally {
    cleanup(dir);
  }
});

test('primary-lock: worker role is blocked and logged to the audit log', () => {
  const config = cloneConfig();
  const dir = tempDir('wtg-primary-worker-');
  try {
    initRepo(dir);
    installPrimaryLockHook(dir, 'test-owner', config);

    const env = primaryLockEnv(config, { role: 'worker' });
    const result = git(['commit', '--allow-empty', '-q', '-m', 'worker commit'], dir, env);
    assert.notEqual(result.status, 0, 'expected the commit to be blocked');
    assert.match(result.stderr, /BLOCKED/);

    const auditLog = readFileSync(primaryAuditLogPath(dir, config), 'utf8');
    assert.match(auditLog, /decision=blocked/);
  } finally {
    cleanup(dir);
  }
});

test('primary-lock: the allow-env escape hatch permits a worker-role write and is logged as such', () => {
  const config = cloneConfig();
  const dir = tempDir('wtg-primary-allow-');
  try {
    initRepo(dir);
    installPrimaryLockHook(dir, 'test-owner', config);

    const env = primaryLockEnv(config, { role: 'worker', primaryLockAllow: '1' });
    const result = git(['commit', '--allow-empty', '-q', '-m', 'allowed worker commit'], dir, env);
    assert.equal(result.status, 0, `expected allowed: ${result.stderr}`);

    const auditLog = readFileSync(primaryAuditLogPath(dir, config), 'utf8');
    assert.match(auditLog, new RegExp(`reason=escape-hatch-${config.envVars.primaryLockAllow}`));
  } finally {
    cleanup(dir);
  }
});

test('primary-lock: git fetch (refs/remotes/*) is never blocked, even in a worker context', () => {
  const config = cloneConfig();
  const remoteDir = tempDir('wtg-primary-remote-');
  const dir = tempDir('wtg-primary-fetch-');
  try {
    initRepo(remoteDir);
    initRepo(dir);
    installPrimaryLockHook(dir, 'test-owner', config);
    runOk(['remote', 'add', 'origin', remoteDir], dir);

    const env = primaryLockEnv(config, { role: 'worker' });
    const result = git(['fetch', 'origin'], dir, env);
    assert.equal(result.status, 0, `expected fetch to succeed: ${result.stderr}`);

    const remoteRef = runOk(['rev-parse', '--verify', 'refs/remotes/origin/main'], dir);
    assert.ok(remoteRef.stdout.length > 0);
  } finally {
    cleanup(remoteDir, dir);
  }
});

test('primary-lock: refs/tags, refs/notes, and the internal ref namespace are always allowed', () => {
  const config = cloneConfig();
  const dir = tempDir('wtg-primary-allowlist-');
  try {
    initRepo(dir);
    installPrimaryLockHook(dir, 'test-owner', config);
    const env = primaryLockEnv(config, { role: 'worker' });

    const tag = git(['tag', 'my-tag'], dir, env);
    assert.equal(tag.status, 0, `tag should be allowed: ${tag.stderr}`);

    const note = git(['-c', 'user.name=Fixture', '-c', 'user.email=fixture@example.test', 'notes', 'add', '-m', 'note body'], dir, env);
    assert.equal(note.status, 0, `notes should be allowed: ${note.stderr}`);

    const headSha = runOk(['rev-parse', 'HEAD'], dir).stdout;
    const internalRef = git(
      ['update-ref', `refs/${config.internalRefNamespace}/test-ref`, headSha],
      dir,
      env,
    );
    assert.equal(internalRef.status, 0, `internal ref should be allowed: ${internalRef.stderr}`);
  } finally {
    cleanup(dir);
  }
});

test('primary-lock: multi-layer ancestor directory-segment walk matches process-provenance.mjs exactly', () => {
  const config = cloneConfig();

  // A globally-installed AI CLI's script can live an arbitrary number of
  // directory levels below the tool's own home dir (".claude" here is the
  // GRANDPARENT of cli.js, not its direct parent) -- this must still hit.
  const hitCommand = 'node /home/user/.claude/local/cli.js';
  // A directory name that merely CONTAINS "claude" as a substring of a
  // longer segment must never hit -- matching is whole-segment only.
  const missCommand = 'bash /tmp/xxxxxx/claude-scratch-lane-abc123/cli.js';

  // Double verification against the JS-side matcher before touching the
  // bash hook at all: the two implementations must agree on both cases.
  assert.equal(matchesAiParentProcess(hitCommand, config), true);
  assert.equal(matchesAiParentProcess(missCommand, config), false);

  const dirHit = tempDir('wtg-primary-ancestor-hit-');
  const dirMiss = tempDir('wtg-primary-ancestor-miss-');
  try {
    initRepo(dirHit);
    installPrimaryLockHook(dirHit, 'test-owner', config);
    // Script the entire process inventory here instead of replacing only the
    // test runner PID. On Windows, Git-for-Windows adds several real launcher
    // processes between the test runner and the hook; inheriting that chain
    // made this POSIX-command fixture dependent on CIM/ps ancestry details.
    // The same bounded launcher inventory is used by the Windows-path case
    // below, while the final ancestor row remains the POSIX command under
    // test here.
    resetFakePsChain(dirHit);
    const hitEnv = primaryLockEnv(config, { fakeChain: true, fakeChainFinal: hitCommand });
    const hitResult = git(['commit', '--allow-empty', '-q', '-m', 'ancestor hit'], dirHit, hitEnv);
    assert.notEqual(hitResult.status, 0, 'expected the multi-layer ancestor match to block');
    assert.match(hitResult.stderr, /BLOCKED/);

    initRepo(dirMiss);
    installPrimaryLockHook(dirMiss, 'test-owner', config);
    resetFakePsChain(dirMiss);
    const missEnv = primaryLockEnv(config, { fakeChain: true, fakeChainFinal: missCommand });
    const missResult = git(['commit', '--allow-empty', '-q', '-m', 'ancestor miss'], dirMiss, missEnv);
    assert.equal(
      missResult.status,
      0,
      `expected allowed -- a substring-only match must never block: ${missResult.stderr}`,
    );
  } finally {
    cleanup(dirHit, dirMiss);
  }
});

test('primary-lock: Windows process paths survive launcher layers and exact directory matching', () => {
  const config = cloneConfig();
  const windowsExe = String.raw`C:\Program Files\nodejs\node.exe`;
  const windowsAiScript = String.raw`C:\Users\RUNNER~1\AppData\Roaming\npm\node_modules\claude-code\.claude\local\cli.js`;
  const windowsMissScript = String.raw`C:\Users\RUNNER~1\AppData\Local\Temp\claude-scratch-lane-abc123\local\cli.js`;
  const hitCommand = `"${windowsExe}" "${windowsAiScript}"`;
  const missCommand = `"${windowsExe}" "${windowsMissScript}"`;

  // Exercise the JS matcher with its reliable-executable form, which carries
  // the full executable separately from its command-line arguments.
  assert.equal(matchesAiParentProcess(`${windowsExe}\u0000${windowsAiScript}`, config), true);
  assert.equal(matchesAiParentProcess(`${windowsExe}\u0000${windowsMissScript}`, config), false);

  const dirHit = tempDir('wtg-primary-windows-ancestor-hit-');
  const dirMiss = tempDir('wtg-primary-windows-ancestor-miss-');
  try {
    initRepo(dirHit);
    installPrimaryLockHook(dirHit, 'test-owner', config);
    resetFakePsChain(dirHit);
    const hitResult = git(
      ['commit', '--allow-empty', '-q', '-m', 'windows ancestor hit'],
      dirHit,
      primaryLockEnv(config, { fakeChain: true, fakeChainFinal: hitCommand }),
    );
    assert.notEqual(hitResult.status, 0, `Windows AI script ancestor must block through launcher processes: ${hitResult.stderr}`);
    assert.match(hitResult.stderr, /BLOCKED/);

    initRepo(dirMiss);
    installPrimaryLockHook(dirMiss, 'test-owner', config);
    resetFakePsChain(dirMiss);
    const missResult = git(
      ['commit', '--allow-empty', '-q', '-m', 'windows ancestor miss'],
      dirMiss,
      primaryLockEnv(config, { fakeChain: true, fakeChainFinal: missCommand }),
    );
    assert.equal(
      missResult.status,
      0,
      `Windows substring-only directory must remain allowed: ${missResult.stderr}`,
    );
  } finally {
    cleanup(dirHit, dirMiss);
  }
});

test('installPrimaryLockHook is a true no-op on a second call when nothing changed', () => {
  const config = cloneConfig();
  const dir = tempDir('wtg-primary-idempotent-');
  try {
    initRepo(dir);
    installPrimaryLockHook(dir, 'owner-1', config);
    const hookFile = join(dir, '.git', 'primary-lock-hooks', 'reference-transaction');
    const before = readFileSync(hookFile, 'utf8');
    const beforeMtime = statSync(hookFile).mtimeMs;

    installPrimaryLockHook(dir, 'owner-1', config);
    const after = readFileSync(hookFile, 'utf8');
    const afterMtime = statSync(hookFile).mtimeMs;

    assert.equal(after, before);
    assert.equal(afterMtime, beforeMtime, 'file must not be rewritten when content is unchanged');
  } finally {
    cleanup(dir);
  }
});

test('refreshPrimaryLockHookIfStale never performs a first install, but refreshes once installed', () => {
  const config = cloneConfig();
  const dir = tempDir('wtg-primary-refresh-');
  try {
    initRepo(dir);
    assert.equal(primaryLockHookIsInstalled(dir, config), false);

    refreshPrimaryLockHookIfStale(dir, 'owner', config);
    assert.equal(primaryLockHookIsInstalled(dir, config), false, 'must not perform a first install');

    installPrimaryLockHook(dir, 'owner', config);
    assert.equal(primaryLockHookIsInstalled(dir, config), true);

    refreshPrimaryLockHookIfStale(dir, 'owner', config);
    assert.equal(primaryLockHookIsInstalled(dir, config), true);
  } finally {
    cleanup(dir);
  }
});

test('sweepStaleSharedHooksPath clears a core.hooksPath that leaked into the shared config', () => {
  const config = cloneConfig();
  const dir = tempDir('wtg-sweep-');
  try {
    initRepo(dir);
    const hooksDir = join(dir, '.git', 'stash-guard-hooks');
    mkdirSync(hooksDir, { recursive: true });

    const commonDir = runOk(['rev-parse', '--git-common-dir'], dir).stdout;
    const absoluteCommonDir = commonDir.startsWith('/') ? commonDir : join(dir, commonDir);
    const commonConfigPath = join(absoluteCommonDir, 'config');
    runOk(['config', '--file', commonConfigPath, 'core.hooksPath', hooksDir], dir);

    sweepStaleSharedHooksPath(dir, hooksDir, config);

    const after = git(['config', '--file', commonConfigPath, '--get', 'core.hooksPath'], dir);
    assert.notEqual(after.status, 0, 'core.hooksPath should have been unset from the shared config');
  } finally {
    cleanup(dir);
  }
});

