test('createBypassMarker writes a marker file that removeBypassMarker deletes', () => {
  const dir = tempDir('wtg-marker-');
  try {
    const hooksDir = join(dir, 'primary-lock-hooks');
    const markerPath = createBypassMarker(hooksDir);
    assert.ok(existsSync(markerPath));
    assert.match(readFileSync(markerPath, 'utf8'), new RegExp(`^${process.pid}\\n`));

    removeBypassMarker(markerPath);
    assert.equal(existsSync(markerPath), false);
  } finally {
    cleanup(dir);
  }
});

test('computeStamp is deterministic for identical input and changes when the input changes', () => {
  const stampA = computeStamp('same body');
  const stampB = computeStamp('same body');
  const stampC = computeStamp('a different body');
  assert.equal(stampA, stampB);
  assert.notEqual(stampA, stampC);
  assert.match(stampA, /^[0-9a-f]{12}-[0-9a-f]{12}$/);
});
